package org.apache.commons.math3.util;

import org.junit.Test;
import org.apache.commons.math3.exception.ConvergenceException;
import static org.junit.Assert.*;

public class AgentBRT_Math_31_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        ContinuedFraction cf = new ContinuedFraction() {
            @Override
            protected double getA(int n, double x) {
                return n == 0 ? 1.0 : 1.0 / (n * n);
            }

            @Override
            protected double getB(int n, double x) {
                return 1.0;
            }
        };

        try {
            cf.evaluate(1.0, 1e-10, 10);
            fail("Expected ConvergenceException due to non-convergence or infinite values.");
        } catch (ConvergenceException e) {
            // Expected exception due to divergence or infinite values
        }
    }
}

